import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

avg_pool2d_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void avg_pool2d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * channels * output_height * output_width;
    if (idx < total) {
        int w_out = idx % output_width;
        int h_out = (idx / output_width) % output_height;
        int c = (idx / (output_width * output_height)) % channels;
        int n = idx / (output_width * output_height * channels);

        int h_start = h_out * stride - padding;
        int w_start = w_out * stride - padding;

        float sum_val = 0.0f;
        int count = 0;

        for (int i = 0; i < kernel_size; i++) {
            for (int j = 0; j < kernel_size; j++) {
                int h_in = h_start + i;
                int w_in = w_start + j;
                if (h_in >= 0 && h_in < input_height && w_in >= 0 && w_in < input_width) {
                    int index_in = ((n * channels + c) * input_height + h_in) * input_width + w_in;
                    sum_val += input[index_in];
                    count++;
                }
            }
        }
        float avg_val = sum_val / float(kernel_size * kernel_size);
        // (Optional) If you only want to average over valid elements counted, use: sum_val / float(count)
        int index_out = ((n * channels + c) * output_height + h_out) * output_width + w_out;
        output[index_out] = avg_val;
    }
}

torch::Tensor avg_pool2d_cuda(
    torch::Tensor x,
    int kernel_size,
    int stride,
    int padding
) {
    // Ensure input is contiguous
    x = x.contiguous();

    auto b = x.size(0);
    auto c = x.size(1);
    auto h = x.size(2);
    auto w = x.size(3);

    // Compute output dimensions
    int out_h = static_cast<int>(std::floor((float)(h + 2*padding - kernel_size) / stride)) + 1;
    int out_w = static_cast<int>(std::floor((float)(w + 2*padding - kernel_size) / stride)) + 1;

    auto options = torch::TensorOptions().dtype(x.dtype()).device(x.device());
    auto out = torch::empty({b, c, out_h, out_w}, options);

    int total = b * c * out_h * out_w;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    avg_pool2d_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        b, c, h, w, out_h, out_w,
        kernel_size, stride, padding
    );

    return out;
}
'''

avg_pool2d_cpp_source = r'''
torch::Tensor avg_pool2d_cuda(
    torch::Tensor x,
    int kernel_size,
    int stride,
    int padding
);
'''

my_avg_pool2d = load_inline(
    name="my_avg_pool2d",
    cpp_sources=avg_pool2d_cpp_source,
    cuda_sources=avg_pool2d_source,
    functions=["avg_pool2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Model that performs 2D Average Pooling using a custom CUDA kernel.
    """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return my_avg_pool2d.avg_pool2d_cuda(x, self.kernel_size, self.stride, self.padding)
